<?php
require_once __DIR__ . '/../auth/check.php'; requireRole('Admin'); require_once __DIR__ . '/../config/database.php';
$rows=$pdo->query("SELECT dl.MaDatLich,bn.HoTen AS BenhNhan,bs.HoTen AS BacSi,ck.TenChuyenKhoa,lk.NgayKham,lk.GioBatDau,dl.TrangThai FROM DatLich dl JOIN BenhNhan bn ON dl.MaBN=bn.MaBN JOIN LichKham lk ON dl.MaLich=lk.MaLich JOIN BacSi bs ON lk.MaBS=bs.MaBS JOIN ChuyenKhoa ck ON bs.MaCK=ck.MaCK ORDER BY lk.NgayKham DESC,lk.GioBatDau")->fetchAll();
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lịch hẹn</title><link href="../assets/vendor/bootstrap/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between mb-3"><h2>Quản lý lịch hẹn</h2><a href="dashboard.php" class="btn btn-outline-secondary">Dashboard</a></div><table class="table table-bordered"><thead><tr><th>Mã</th><th>Bệnh nhân</th><th>Bác sĩ</th><th>Chuyên khoa</th><th>Ngày</th><th>Giờ</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= $r['MaDatLich'] ?></td><td><?= htmlspecialchars($r['BenhNhan']) ?></td><td><?= htmlspecialchars($r['BacSi']) ?></td><td><?= htmlspecialchars($r['TenChuyenKhoa']) ?></td><td><?= $r['NgayKham'] ?></td><td><?= substr($r['GioBatDau'],0,5) ?></td><td><?= $r['TrangThai'] ?></td></tr><?php endforeach; ?></tbody></table></div></body></html>
